function parseDuration(s: string): number {
  const valid = /^\d+[hms]?((\s+|,\s+)?\d+[hms]?)?$/;

  if (!valid.test(s)) {
    throw new Error(`invalid duration: ${s}`);
  }

  let total = 0;
  for (const match of s.matchAll(/(\d+)([hms])?/g)) {
    const num = parseInt(match[1], 10);
    const unit = match[2];
    if (unit === "h") {
      total += num * 3600;
    } else if (unit === "m") {
      total += num * 60;
    } else {
      total += num;
    }
  }

  return total;
}

function parseDuration(s: string): number {
  // Bare number (no unit) means seconds
  if (/^\d+$/.test(s)) {
    return parseInt(s, 10);
  }

  // Full pattern: one or more \d+[hms] components, optionally separated by whitespace or ", "
  const fullPattern = /^\d+[hms](?:(?:\s+|,\s+)\d+[hms])*$/;
  if (!fullPattern.test(s)) {
    throw new Error(`invalid duration: ${s}`);
  }

  // Extract all components and sum them up
  const components = s.match(/\d+[hms]/g)!;
  let total = 0;
  for (const comp of components) {
    const num = parseInt(comp.slice(0, -1), 10);
    const unit = comp.slice(-1);
    if (unit === 'h') {
      total += num * 3600;
    } else if (unit === 'm') {
      total += num * 60;
    } else {
      total += num;
    }
  }
  return total;
}

