export function parseDuration(s: string): number {
  const original = s;

  if (s.length === 0) {
    throw new Error(`invalid duration: ${original}`);
  }

  let i = 0;
  let total = 0;
  let first = true;

  const isDigit = (ch: string) => ch >= '0' && ch <= '9';
  const isWhitespace = (ch: string) => ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f' || ch === '\v';
  const isUnit = (ch: string) => ch === 'h' || ch === 'm' || ch === 's';

  while (i < s.length) {
    if (!first) {
      if (s[i] === ',') {
        i++;
        const wsStart = i;
        while (i < s.length && isWhitespace(s[i])) {
          i++;
        }
        if (i === wsStart) {
          throw new Error(`invalid duration: ${original}`);
        }
      } else {
        while (i < s.length && isWhitespace(s[i])) {
          i++;
        }
      }
    }

    const numStart = i;
    while (i < s.length && isDigit(s[i])) {
      i++;
    }
    if (i === numStart) {
      throw new Error(`invalid duration: ${original}`);
    }

    const numStr = s.slice(numStart, i);
    const num = parseInt(numStr, 10);

    let unit = '';
    if (i < s.length && isUnit(s[i])) {
      unit = s[i];
      i++;
    }

    switch (unit) {
      case 'h':
        total += num * 3600;
        break;
      case 'm':
        total += num * 60;
        break;
      case 's':
        total += num;
        break;
      case '':
        total += num;
        break;
      default:
        throw new Error(`invalid duration: ${original}`);
    }

    first = false;
  }

  return total;
}

function invalidError(s: string): Error {
  return new Error(`invalid duration: ${s}`);
}

export function parseDuration(s: string): number {
  if (s.length === 0) {
    throw invalidError(s);
  }

  // Bare number (no units at all) means seconds.
  if (/^\d+$/.test(s)) {
    return parseInt(s, 10);
  }

  let total = 0;
  let i = 0;
  let first = true;

  while (i < s.length) {
    if (!first) {
      let j = i;
      if (s[j] === ',') {
        j++;
        let wsCount = 0;
        while (j < s.length && /\s/.test(s[j])) {
          j++;
          wsCount++;
        }
        if (wsCount === 0) {
          throw invalidError(s);
        }
        i = j;
      } else {
        while (j < s.length && /\s/.test(s[j])) {
          j++;
        }
        i = j;
      }
    }

    const numStart = i;
    while (i < s.length && /\d/.test(s[i])) {
      i++;
    }

    if (i === numStart) {
      throw invalidError(s);
    }

    const numStr = s.slice(numStart, i);

    if (i >= s.length) {
      throw invalidError(s);
    }

    const unit = s[i];
    if (unit !== 'h' && unit !== 'm' && unit !== 's') {
      throw invalidError(s);
    }
    i++;

    const num = parseInt(numStr, 10);
    if (unit === 'h') {
      total += num * 3600;
    } else if (unit === 'm') {
      total += num * 60;
    } else {
      total += num;
    }

    first = false;
  }

  if (first) {
    // No component was ever parsed.
    throw invalidError(s);
  }

  return total;
}
